program = '''def transform(grid):
    nrows = len(grid)
    ncols = len(grid[0])
    out = [row[:] for row in grid]

    def equivalents(r, c):
        seen = {(r, c)}
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            candidates = [(y, x), (31 - x, y), (y, 31 - x)]
            for a, b in candidates:
                if 0 <= a < nrows and 0 <= b < ncols and (a, b) not in seen:
                    seen.add((a, b))
                    stack.append((a, b))
        return seen

    for r in range(nrows):
        for c in range(ncols):
            if grid[r][c] == 6:
                for a, b in equivalents(r, c):
                    if grid[a][b] != 6:
                        out[r][c] = grid[a][b]
                        break
    return out
'''
