def known_orbit_values(g,r,c):
    return {(a,b,g[a][b]) for a,b in equivalents_for_check(g,r,c) if g[a][b]!=6}
def equivalents_for_check(g,r,c):
    seen={(r,c)}; stack=[(r,c)]
    while stack:
        x,y=stack.pop()
        for a,b in ((y,x),(31-x,y),(y,31-x)):
            if 0<=a<len(g) and 0<=b<len(g[0]) and (a,b) not in seen:
                seen.add((a,b)); stack.append((a,b))
    return seen
